import{_ as t,o as n,c as o,ag as s}from"./chunks/framework.D5hoimZQ.js";const d=JSON.parse('{"title":"🔬 科学快报 | 2026年9月1日（事后重建版）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"science-log/src/reconstructed/2026-09-01.md","filePath":"science-log/src/reconstructed/2026-09-01.md"}'),e={name:"science-log/src/reconstructed/2026-09-01.md"};function a(g,r,i,l,c,p){return n(),o("div",null,[...r[0]||(r[0]=[s('<h1 id="🔬-科学快报-2026年9月1日-事后重建版" tabindex="-1">🔬 科学快报 | 2026年9月1日（事后重建版） <a class="header-anchor" href="#🔬-科学快报-2026年9月1日-事后重建版" aria-label="Permalink to &quot;🔬 科学快报 | 2026年9月1日（事后重建版）&quot;">​</a></h1><blockquote><p>⚠️ <strong>事后重建版</strong>：本文件<strong>不是</strong>当日发布原文。由 2026-11-05 依 arXiv / CrossRef <strong>按发布日期回溯检索</strong>生成，选题与排序均为事后判定，<strong>不代表历史原貌</strong>。 说明：2026-09-01 为<strong>周二</strong>。CrossRef 精确当日命中：Nature（0028-0836）<strong>19 条，其中 <code>10.1038/s41586-…</code> 研究论文 0 条</strong>（唯一一条 <code>s41586</code> 为 Author Correction，已剔除；其余为 <code>d41586-…</code> 新闻/Briefing，已丢弃）；Science 系（10.1126）<strong>11 条</strong>，研究论文仅 <strong>Science Signaling 1 篇</strong>（<code>scisignal.aef0939</code>，其余为 <code>science.z…</code> 新闻稿与 Science Adviser）；PNAS（0027-8424）<strong>21 条</strong>（含 20 篇研究论文）。故<strong>科学 5 篇取 PNAS ×4 + Science Signaling ×1</strong>。<strong>AI 5 篇</strong>取自当日 arXiv cs.AI 提交（submittedDate <code>[202609010000 TO 202609012359]</code>，<code>totalResults</code> 243 篇）。期号因当日原本无刊期，标为 <code>（第 ? 期 · 事后重建版）</code>。 取证：CrossRef（Nature 0028-0836 / Science 10.1126 / PNAS 0027-8424）+ arXiv 日期区间 <code>[202609010000 TO 202609012359]</code>（cs.AI）｜ 重建日：2026-11-05</p></blockquote><h2 id="🔬-科学前沿" tabindex="-1">🔬 科学前沿 <a class="header-anchor" href="#🔬-科学前沿" aria-label="Permalink to &quot;🔬 科学前沿&quot;">​</a></h2><h3 id="🌫️-用视觉-transformer-从-emit-高光谱辐亮度全球监测甲烷点源" tabindex="-1">🌫️ 用视觉 Transformer 从 EMIT 高光谱辐亮度全球监测甲烷点源 <a class="header-anchor" href="#🌫️-用视觉-transformer-从-emit-高光谱辐亮度全球监测甲烷点源" aria-label="Permalink to &quot;🌫️ 用视觉 Transformer 从 EMIT 高光谱辐亮度全球监测甲烷点源&quot;">​</a></h3><p><strong>Global monitoring of methane point sources using deep learning on hyperspectral radiance measurements from EMIT</strong><em>PNAS（2026-09-01）</em></p><p>人为甲烷<strong>点源</strong>是短期气候强迫、安全隐患与系统低效的关键推手；星载成像光谱是识别排放的新手段，但既有方法<strong>多依赖人工勾绘羽流</strong>。Batchu、Conserva、Wilson、Michalak 等（8 位作者）提出 <strong>MAPL-EMIT</strong>：一个端到端 <strong>视觉 Transformer</strong> 框架，直接用 <strong>EMIT 仪器完整的辐亮度谱</strong>，<strong>在全场景所有像素上联合反演甲烷增强</strong>，把光谱信息与<strong>空间上下文</strong>结合，从而<strong>显著压低检测限</strong>。模型在注入全球 EMIT 辐亮度的 <strong>360 万个物理仿真羽流</strong>上训练，同时支持<strong>增强量化、羽流勾绘与源定位</strong>，即便<strong>羽流重叠</strong>也能分辨。</p><p>📎 DOI: <a href="https://doi.org/10.1073/pnas.2612145123" target="_blank" rel="noreferrer">10.1073/pnas.2612145123</a></p><h3 id="🧠-单个胞外糖链把-ampa-受体门控与突触可塑性、记忆持久性连起来" tabindex="-1">🧠 单个胞外糖链把 AMPA 受体门控与突触可塑性、记忆持久性连起来 <a class="header-anchor" href="#🧠-单个胞外糖链把-ampa-受体门控与突触可塑性、记忆持久性连起来" aria-label="Permalink to &quot;🧠 单个胞外糖链把 AMPA 受体门控与突触可塑性、记忆持久性连起来&quot;">​</a></h3><p><strong>A single extracellular glycan links AMPA receptor gating to synaptic plasticity and memory persistence</strong><em>PNAS（2026-09-01）</em></p><p>持久突触可塑性是记忆的基础，但其<strong>稳定机制</strong>尚不完全清楚。AMPA 型谷氨酸受体介导脑中大部分快速兴奋性传递，然而<strong>胞外翻译后修饰</strong>如何在体内调控其功能动态仍不明。Midorikawa、Wakazono、Kandel 等（10 位作者）鉴定出 <strong>GluA1 亚基 Asn401 上的单个内源 N-连接糖链</strong>：缺失该糖链会<strong>显著降低 AMPAR 失敏、促进复敏</strong>；生化与成像显示，无 N401 糖链的 GluA1 通过<strong>增强与神经节苷脂结合</strong>而<strong>优先分配进富含神经节苷脂的脂筏微域</strong>，扰乱活动依赖的受体转运、促进<strong>过度内吞</strong>。用 <strong>GluA1 N401Q 敲入小鼠</strong>证明，缺失该糖链<strong>选择性地损害海马</strong>依赖性记忆。</p><p>📎 DOI: <a href="https://doi.org/10.1073/pnas.2607934123" target="_blank" rel="noreferrer">10.1073/pnas.2607934123</a></p><h3 id="🧬-脑相关性状的遗传结构为何「命中弱、频率高」——强选择约束" tabindex="-1">🧬 脑相关性状的遗传结构为何「命中弱、频率高」——强选择约束 <a class="header-anchor" href="#🧬-脑相关性状的遗传结构为何「命中弱、频率高」——强选择约束" aria-label="Permalink to &quot;🧬 脑相关性状的遗传结构为何「命中弱、频率高」——强选择约束&quot;">​</a></h3><p><strong>Genetic architectures of brain-related traits are shaped by strong selective constraints</strong><em>PNAS（2026-09-01）</em></p><p>GWAS 已为精神疾病找到数百个显著位点，但其<strong>效应强度</strong>却普遍逊于命中数相近的其它复杂性状。Zhu、Simons、Spence、Sella、Pritchard（5 位作者）发现：<strong>凡在 CNS 功能上富集的性状</strong>（无论二元还是定量）都共享<strong>相似的遗传结构</strong>——GWAS 命中<strong>统计显著性受限</strong>、<strong>等位基因频率普遍偏高</strong>。在<strong>校正二元/定量研究的统计功效差异</strong>后，他们拟合<strong>演化模型</strong>，表明 CNS 富集性状具有<strong>大的突变靶标</strong>，其贡献变异与基因<strong>承受更强的选择约束</strong>。这提示该模式<strong>不是统计假象</strong>，而是<strong>真实生物学差异</strong>。</p><p>📎 DOI: <a href="https://doi.org/10.1073/pnas.2609814123" target="_blank" rel="noreferrer">10.1073/pnas.2609814123</a></p><h3 id="🩸-orai1-与-stim1-驱动「毛细血管→小动脉」的神经血管耦合通讯" tabindex="-1">🩸 ORAI1 与 STIM1 驱动「毛细血管→小动脉」的神经血管耦合通讯 <a class="header-anchor" href="#🩸-orai1-与-stim1-驱动「毛细血管→小动脉」的神经血管耦合通讯" aria-label="Permalink to &quot;🩸 ORAI1 与 STIM1 驱动「毛细血管→小动脉」的神经血管耦合通讯&quot;">​</a></h3><p><strong>ORAI Ca²⁺ channels and STIM1 drive capillary-to-arteriole communication in neurovascular coupling</strong><em>Science Signaling（2026-09-01）</em></p><p>神经血管耦合（NVC）由<strong>脑内致密毛细血管网</strong>发起，让血流匹配神经元活动。Lavanderos、Sanchez-Solano、Trebak、Earley 等（9 位作者）发现，库操纵性钙内流的主要驱动者 <strong>ORAI1 通道</strong>及其调控因子 <strong>STIM1</strong>，对**「毛细血管（探测神经元代谢需求）→上游小动脉（舒张以增加局部血流）」<strong>的通讯</strong>不可或缺**：内皮细胞特异性敲除 <em>Stim1</em> 或 <em>Orai1</em> 会<strong>扰乱毛细血管 Ca²⁺ 信号、损害持续的毛细血管驱动小动脉舒张</strong>，并在<strong>胡须刺激</strong>下<strong>降低躯体感觉皮层的血流增幅</strong>——说明 ORAI1/STIM1 <strong>在长时间神经刺激中维持脑血流</strong>。</p><p>📎 DOI: <a href="https://doi.org/10.1126/scisignal.aef0939" target="_blank" rel="noreferrer">10.1126/scisignal.aef0939</a></p><h3 id="🌊-在「关联无序」中实验性控制水波散射——隐身超均匀介质" tabindex="-1">🌊 在「关联无序」中实验性控制水波散射——隐身超均匀介质 <a class="header-anchor" href="#🌊-在「关联无序」中实验性控制水波散射——隐身超均匀介质" aria-label="Permalink to &quot;🌊 在「关联无序」中实验性控制水波散射——隐身超均匀介质&quot;">​</a></h3><p><strong>Experimentally controlling scattering of water waves in correlated disorder</strong><em>PNAS（2026-09-01）</em></p><p>波在复杂介质中的传播是<strong>跨光学、声学、力学与凝聚态</strong>的普遍问题。无序通常导致强散射，但新理论预言一类特殊的<strong>关联无序</strong>——<strong>隐身超均匀（stealthy hyperuniformity）</strong>——能在<strong>长波长抑制散射</strong>，让介质在<strong>结构仍无序、远离简单均匀化区间</strong>的情况下<strong>变得透明</strong>；然而<strong>介质内部</strong>这一输运区制的实验证据一直有限。Campaniello、Carminati、Filoche、Fort（4 位作者）以<strong>水波为模型平台</strong>，对<strong>振幅与相位</strong>成像，直接、空间分辨地观测到<strong>超均匀关联诱导的「散射↔非散射」输运转变</strong>，并提取<strong>消光长度、统计涨落</strong>等定量输运量。</p><p>📎 DOI: <a href="https://doi.org/10.1073/pnas.2605721123" target="_blank" rel="noreferrer">10.1073/pnas.2605721123</a></p><h2 id="🤖-ai-前沿" tabindex="-1">🤖 AI 前沿 <a class="header-anchor" href="#🤖-ai-前沿" aria-label="Permalink to &quot;🤖 AI 前沿&quot;">​</a></h2><h3 id="🔋-outagedit-面向停电预报与情景生成的电力基础模型" tabindex="-1">🔋 OutageDiT：面向停电预报与情景生成的电力基础模型 <a class="header-anchor" href="#🔋-outagedit-面向停电预报与情景生成的电力基础模型" aria-label="Permalink to &quot;🔋 OutageDiT：面向停电预报与情景生成的电力基础模型&quot;">​</a></h3><p><strong>OutageDiT: A Foundation Model for Power Outage Forecasting and Scenario Generation</strong><em>arXiv（2026-09-01）</em></p><p>停电规划需要<strong>事件发生前的概率情景</strong>——必须刻画量级、时间与持续时长的不确定性，同时保持时间依赖；但<strong>严重事件罕见</strong>，任何单一地区的数据都<strong>缺少极端停电—恢复模式</strong>。Yunqin Zhu、Feng Qiu、Yao Xie（3 位作者）提出 <strong>OutageDiT</strong>：在美国全国停电与气象记录上训练，生成 <strong>15 分钟分辨率、7 天时长</strong>的停电轨迹。其<strong>条件编码器</strong>每次预报处理一次历史上下文与已知未来协变量，<strong>浅层 flow-matching 解码器</strong>复用这些<strong>与预测时域对齐的状态</strong>来采样完整轨迹——从而在<strong>单一深度生成模型</strong>内同时实现<strong>点预报、不确定性量化与条件情景生成</strong>。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2609.01896" target="_blank" rel="noreferrer">2609.01896</a></p><h3 id="🧠-记忆信任鸿沟-持久记忆智能体的「能力越大-越会盲信陈旧事实」" tabindex="-1">🧠 记忆信任鸿沟：持久记忆智能体的「能力越大，越会盲信陈旧事实」 <a class="header-anchor" href="#🧠-记忆信任鸿沟-持久记忆智能体的「能力越大-越会盲信陈旧事实」" aria-label="Permalink to &quot;🧠 记忆信任鸿沟：持久记忆智能体的「能力越大，越会盲信陈旧事实」&quot;">​</a></h3><p><strong>The Memory Trust Gap: Capability-Dependent Failures in Persistent-Memory Agents</strong><em>arXiv（2026-09-01）</em></p><p>持久记忆支撑个性化智能体，但<strong>一条陈旧的存储事实</strong>可能<strong>无警告地压倒当前权威证据</strong>。Jundong Hu、Shekar Ramachandran（2 位作者）研究这种危害<strong>如何随模型能力变化而出现</strong>：用<strong>冻结、闭集、按动作打分</strong>的基准，含两个套件——<strong>Benefit 套件</strong>（没有该存储事实则无解）与 <strong>Safety 套件</strong>（权威工具总是持有正确值）。在<strong>同族模型尺寸序列</strong>（Qwen3 0.6/1.7/4/8B）上：Benefit 套件里模型<strong>在每一尺度都以 0.92–1.00 的概率给出陈旧值</strong>；Safety 套件中，<strong>低于「无记忆」基线的危害（Δ_mem）是能力门控的</strong>——<strong>越大的模型，一旦让陈旧笔记显得「当前」，就越会整体失效</strong>。作者强调这反映的是<strong>过度信任</strong>而非混淆。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2609.01852" target="_blank" rel="noreferrer">2609.01852</a></p><h3 id="🌀-循环-transformer-的雅可比透镜-全局工作空间能否在递归中存活" tabindex="-1">🌀 循环 Transformer 的雅可比透镜：全局工作空间能否在递归中存活？ <a class="header-anchor" href="#🌀-循环-transformer-的雅可比透镜-全局工作空间能否在递归中存活" aria-label="Permalink to &quot;🌀 循环 Transformer 的雅可比透镜：全局工作空间能否在递归中存活？&quot;">​</a></h3><p><strong>Looped Transformers under the Jacobian Lens: Does the Global Workspace Survive Recurrence?</strong><em>arXiv（2026-09-01）</em></p><p>近期工作在前馈 Transformer 中识别出一段<strong>中层、可言语化、具因果效力</strong>的表征带——即**「全局工作空间」的功能类比**。但当深度由<strong>递归</strong>（复用同一组权重）而非<strong>堆叠不同层</strong>实现时，这种工作空间是否仍涌现，尚不清楚。Wenlong Wang、Fergal Reid（2 位作者）用<strong>虚拟展开适配器</strong>把<strong>雅可比透镜</strong>扩展用于迭代架构，对 <strong>Ouro-2.6B</strong>（48 层循环 4 次、深度监督）与 <strong>Huginn-0125</strong>（4 层核心递归 16 次、为潜推理训练）施加<strong>完整工作空间测试组</strong>（透镜拟合、读出与 11 类因果实验），并以 <strong>Qwen3.6-27B</strong>（64 个非绑定层）为常规基线。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2609.01924" target="_blank" rel="noreferrer">2609.01924</a></p><h3 id="🛡️-认识论女巫抵抗-复制-ai-智能体不等于复制证据" tabindex="-1">🛡️ 认识论女巫抵抗：复制 AI 智能体不等于复制证据 <a class="header-anchor" href="#🛡️-认识论女巫抵抗-复制-ai-智能体不等于复制证据" aria-label="Permalink to &quot;🛡️ 认识论女巫抵抗：复制 AI 智能体不等于复制证据&quot;">​</a></h3><p><strong>Epistemic Sybil Resistance: Multiplying AI Agents Without Multiplying Evidence</strong><em>arXiv（2026-09-01）</em></p><p>多智能体 AI 靠<strong>繁殖智能体、汇总报告</strong>来改进推断。但**「另一个智能体」不等于「另一次观测」<strong>：看似独立的报告可能</strong>同源**，而真正独立的证据也可能给出<strong>近乎相同的报告</strong>。Marc Bara 把这一失效形式化为<strong>认识论女巫（epistemic Sybil）问题</strong>——当 <strong>I(Θ; Z | R) = 0</strong> 时称报告 <strong>Z</strong> 是报告集 <strong>R</strong> 的**「认识论女巫扩展」<strong>。结论是：<strong>任何仅看报告的聚合器一般无法区分「复述」与「独立佐证」</strong>——相同的报告在</strong>未观测的谱系（ancestry）<strong>下可支撑不同的后验。一个</strong>高斯共享根模型<strong>显示，<strong>共同祖先不等于完全冗余</strong>：重复抽取会向</strong>源级上限<strong>累加信息，而</strong>相关性抽取误差**（共享基座模型可在「独立」智能体间诱导）会<strong>进一步压低该上限</strong>。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2609.01873" target="_blank" rel="noreferrer">2609.01873</a></p><h3 id="🤔-人与推理模型的「思维努力」在对因推理中对齐" tabindex="-1">🤔 人与推理模型的「思维努力」在对因推理中对齐 <a class="header-anchor" href="#🤔-人与推理模型的「思维努力」在对因推理中对齐" aria-label="Permalink to &quot;🤔 人与推理模型的「思维努力」在对因推理中对齐&quot;">​</a></h3><p><strong>Thinking effort aligns between humans and reasoning models in abductive reasoning</strong><em>arXiv（2026-09-01）</em></p><p>认知建模的一个核心问题，是 LLM 与人类在<strong>语言与非语言任务</strong>上的行为对齐。不同于普通 LLM，<strong>大推理模型（LRM）<strong>用</strong>可验证奖励的强化学习</strong>优化，倾向于<strong>正确解</strong>而非<strong>偏好对齐的回应</strong>。Henry Arthur（1 位作者）以<strong>对因推理（abductive reasoning）<strong>为切口——与演绎任务不同，其</strong>难度无法由形式结构推出</strong>，<strong>无法靠捷径伪装努力而不做真正的搜索</strong>，因而为「共享努力」的经验主张提供<strong>更坚实的地基</strong>；据此发现 LRM 与人类的<strong>思维努力进一步对齐</strong>。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2609.01867" target="_blank" rel="noreferrer">2609.01867</a></p><blockquote><p>📅 日期：2026-09-01 ｜ ⚠️ 事后重建版 ｜ 📂 科学前沿 5 篇 | 🤖 AI前沿 5 篇 ｜ （第 ? 期 · 事后重建版）</p></blockquote>',45)])])}const m=t(e,[["render",a]]);export{d as __pageData,m as default};
